const steps=['09:00 출근','09:10 업무 분담','10:30 업무 지시','14:00 보안 점검','15:00 최종 실습','16:30 팀장 보고'];let state={name:'',step:0,fields:{},answers:{},done:false,token:''},timer;const app=document.getElementById('app');
function esc(x){return String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function field(k,label,placeholder=''){return '<label>'+label+'</label><textarea data-k="'+k+'" placeholder="'+placeholder+'">'+esc(state.fields[k])+'</textarea>'}let portrait='';try{portrait=localStorage.getItem('store-ai-portrait-v1')||''}catch{}
function card(){return '<div class="card '+(state.done?'gold shine':'')+'"><div class="tag">EMPLOYEE CARD</div><p class="card-team">스마트스토어<br>AI 운영팀</p><div class="avatar">'+(portrait?'<img src="'+portrait+'" alt="사원증 사진">':'<span>PHOTO</span>')+'</div><h2 class="card-name">'+esc(state.name||'이름을 입력하세요')+'</h2><b class="card-rank">'+(state.project?.done?'과장':state.done?'대리':'사원')+'</b><div class="barcode"></div></div>'}
const art='<svg class="illustration" viewBox="0 0 400 230" fill="none" stroke="#222" stroke-width="3"><rect x="55" y="20" width="285" height="150" rx="12"/><path d="M80 50h90M80 70h70M80 90h90"/><path fill="#ffa800" d="M195 120V90h24v30zM231 120V65h24v55zM267 120V40h24v80z"/><circle cx="112" cy="157" r="25" fill="#fffbed"/><path d="M60 225q5-49 52-43 44-6 50 43" fill="#ffa800"/><circle cx="260" cy="160" r="25" fill="#fffbed"/><path d="M205 225q10-48 55-43 46-5 53 43" fill="#ffa800"/><path d="M115 150h-6m15 0h6M260 150h-6m15 0h6M109 169q10 8 19 0M255 170q10 8 19 0"/></svg>';
function shell(body){const pct=state.done?100:state.step===2?40+(state.trainingPage||0)*5:state.step===4?80+(state.launchPage||0)*5:state.step*20;return '<div class="row"><span class="tag">DAY 01 / AI 후임 온보딩</span><b>Lv.'+(state.done?5:Math.min(4,Math.floor(pct/20)+1))+'</b></div><progress max="100" value="'+pct+'"></progress><div class="timeline">'+steps.map((s,i)=>'<span class="'+((state.step===4?((state.launchPage||0)===3?5:4):state.step)===i?'active':'')+'">'+s+'</span>').join('')+'</div>'+body}
function choices(id,question,options,correct,explain){return '<div class="panel"><b>'+question+'</b><div class="choices">'+options.map((o,i)=>'<button data-q="'+id+'" data-v="'+i+'" class="'+(state.answers[id]===i?'on':'')+'">'+o+'</button>').join('')+'</div>'+(state.answers[id]!==undefined?'<div class="feedback">'+(state.answers[id]===correct?'✓ 좋은 판단입니다. ':'다시 생각해보세요. ')+explain+'</div>':'')+'</div>'}function navigation(){return '<div class="row"><button class="secondary" id="back">이전단계</button><button id="next">다음단계</button></div><p class="small" id="notice"></p>'}
const trainingTitles=['루키의 첫 결과물','업무 지시 기본기','프롬프트 기법 1 · [ ] 템플릿','프롬프트 기법 2 · 마크다운','프롬프트 기법 3 · 퓨샷'];
const basicQuiz=[['역할','루키가 어떤 담당자로 일할지 알려주는 지시는?',['알아서 잘해 줘.','너는 내가 선택한 직무를 돕는 AI 보조 담당자야.'],1,'담당 역할을 정하면 어떤 관점으로 작업할지 전달할 수 있습니다.'],['목적','완성할 일을 명확히 알려주는 지시는?',['앞에서 선택한 업무 중 내가 맡긴 일을 수행해 줘.','좋은 결과를 만들어 줘.'],0,'완성해야 할 일을 구체적으로 지정합니다.'],['맥락','자료와 상황을 전달하는 올바른 방법은?',['필요한 자료는 적당히 만들어.','제공한 자료와 대상·상황을 참고해 줘.'],1,'AI가 회사 상황이나 실제 자료를 저절로 알지는 못합니다.'],['출력 형태','검토하기 쉬운 결과를 받으려면?',['읽기 쉽게 해 줘.','업무 결과·근거·확인할 일을 3열 표로 정리해 줘.'],1,'결과의 항목과 형식을 구체적으로 지정합니다.'],['제약 조건','없는 정보를 만들지 않게 하려면?',['추측하지 말고 필요한 정보는 먼저 질문해 줘.','빈칸 없이 무조건 완성해 줘.'],0,'부족한 정보는 질문하거나 확인 필요로 표시하도록 합니다.']];
const sampleData={reviews:'가상 고객 리뷰\nR1: 디자인은 예쁜데 뚜껑이 잘 열리지 않아요.\nR2: 가볍고 들고 다니기 편해요.\nR3: 뚜껑을 열 때 힘이 많이 들어요.',product:'가상 상품 정보\n상품: 데일리 백팩\n가격: 39,000원\n특징: 노트북 수납칸, 생활 방수 원단\n주의: 완전 방수 여부는 확인되지 않음',inquiry:'가상 고객 문의\n고객: 주문한 상품이 언제 출발하나요?\n주문 상태: 결제 완료\n출고 예정일: 확인되지 않음\n담당자가 배송 일정을 확인할 예정',meeting:'가상 회의 메모\n신상품 후보 3개를 비교하기로 함.\n비교 기준: 가격, 기능, 고객 요구\n담당자와 제출 기한은 아직 정하지 않음.'};
function outputRule(){const f=state.fields.format||'table';return f==='table'?'# 결과 작성 방식\n- 마크다운 표로 작성해 줘.\n- 열은 업무 결과 | 자료의 근거 | 내가 확인할 일로 구성해 줘.\n- 핵심 내용은 **굵게** 표시해 줘.':f==='list'?'# 결과 작성 방식\n- 제목과 글머리표 목록으로 정리해 줘.\n- 업무 결과, 자료의 근거, 내가 확인할 일을 각각 구분해 줘.\n- 핵심 내용은 **굵게** 표시해 줘.':'# 결과 작성 방식\n- 초안, 작성 근거, 내가 확인할 일을 제목으로 구분해 줘.\n- 초안은 실제 업무에 맞는 문장으로 작성해 줘.\n- 핵심 내용은 **굵게** 표시해 줘.';}
function emailInput(k,label,placeholder){return '<label for="'+k+'">'+label+'</label><input id="'+k+'" data-k="'+k+'" value="'+esc(state.fields[k]||'')+'" placeholder="'+esc(placeholder)+'">';}
function emailTemplate(){return '너는 우리 팀의 업무를 돕는 AI 비서야.\n아래 정보를 바탕으로 팀 회의 소집 이메일 초안을 작성해 줘.\n\n수신자: [수신자]\n회의 목적: [회의 목적]\n일시: [일시]\n장소: [장소]\n준비 사항: [준비 사항]\n말투: [말투]\n\n제목 → 인사 → 회의 목적 → 일시·장소·준비 사항 → 마무리 순서로 작성해 줘.\n제공하지 않은 날짜·장소·참석자·결정사항은 만들지 마.\n빠진 필수 정보가 있으면 초안을 작성하기 전에 먼저 질문해 줘.\n이메일을 실제로 발송하지 말고 검토용 초안만 작성해 줘.';}
function emailPromptHtml(){const f=state.fields;const values={'수신자':f.meetingTo,'회의 목적':f.meetingPurpose,'일시':f.meetingTime,'장소':f.meetingPlace,'준비 사항':f.meetingPrepare,'말투':f.meetingTone};return esc(emailTemplate()).replace(/\[([^\]]+)\]/g,(m,k)=>'<mark class="template-value">['+esc(values[k]?.trim()||k)+']</mark>');}
function emailPrompt(second=false){const f=state.fields;const values={'수신자':f.meetingTo,'회의 목적':f.meetingPurpose,'일시':second?f.meetingTime2:f.meetingTime,'장소':f.meetingPlace,'준비 사항':f.meetingPrepare,'말투':f.meetingTone};return emailTemplate().replace(/\[([^\]]+)\]/g,(m,k)=>values[k]?.trim()||m);}

function defaultMeetingNotes(){return '실습용 가상 회의 메모\n회의 주제: '+(state.fields.meetingPurpose||state.fields.selectedTask||'선택한 업무')+'\n회의 일시: '+(state.fields.meetingTime||'앞에서 정한 일시')+'\n회의 장소: '+(state.fields.meetingPlace||'앞에서 정한 장소')+'\n\n업무에 참고할 자료 3건 검토 완료. 자료 비교는 진행 중.\n비교 기준은 고객 요구와 실행 가능성으로 정하기로 함.\n가상 팀원 A가 자료를 기준별로 정리하고 다음 회의 전까지 공유하기로 함.\n가상 팀원 B는 추가로 필요한 자료를 확인하기로 함. 기한은 정하지 못함.\n최종 방향은 아직 결정하지 못했으며, 추가 자료 검토 후 다시 논의하기로 함.';}
function markdownModel(){return '아래 회의 메모를 마크다운 형식의 회의록으로 정리해 줘.\n\n1. 회의 주제를 큰 제목으로 쓰고, 주요 논의·결정사항과 다음 할 일·미결 안건으로 소제목을 나눠 줘.\n2. 주요 논의와 미결 안건은 글머리표 목록으로 정리해 줘.\n3. 결정사항과 다음 할 일은 내용 | 담당자 | 기한 열을 가진 표로 작성해 줘.\n4. 중요한 결정사항은 굵게 표시해 줘.\n5. 메모에 없는 정보는 추측하지 말고 확인 필요라고 표시해 줘.';}
function minutesPrompt(){return markdownModel()+'\n\n[원본 회의 메모]\n'+(state.fields.meetingNotes??defaultMeetingNotes());}
const teamExamples=[{title:'고객 문의 분석 진행 보고',rows:['고객 문의 20건을 유형별로 분류함.','배송 일정에 관한 문의가 8건으로 가장 많았음.','배송 안내 문구를 보완할 예정임.','안내 문구에 넣을 출고 기준을 담당자에게 확인해야 함.']},{title:'상품 비교 진행 보고',rows:['후보 상품 3개의 가격과 기능을 비교함.','가격 차이는 확인했으나, 실제 사용 편의성은 확인하지 못함.','샘플 검토 후 추천 상품을 정할 예정임.','샘플 제공 여부와 검토 일정을 확인해야 함.']}];
const reportLabels=['진행 상황','핵심 내용','다음 할 일','확인 필요'];
function exampleText(i){const e=teamExamples[i];return '['+e.title+']\n'+e.rows.map((t,j)=>reportLabels[j]+': '+t).join('\n');}
function fewshotRequest(){return '예시 1과 예시 2는 우리 팀의 업무 보고 문서야.\n두 예시와 같은 문체와 양식으로 아래 회의 메모를 팀장에게 보고할 문서로 작성해 줘.\n\n- 제목과 4개 항목의 순서를 유지해 줘.\n- 각 항목은 짧고 사실 중심인 ~함 문체로 작성해 줘.\n- 예시 속 업무 내용과 수치는 새 보고서에 가져오지 마.\n- 새 보고서의 사실은 회의 메모만 근거로 작성해 줘.\n- 메모에 없는 정보는 확인 필요라고 표시해 줘.';}
function workPrompt(){return '[우리 팀의 작성 예시 1]\n'+exampleText(0)+'\n\n[우리 팀의 작성 예시 2]\n'+exampleText(1)+'\n\n[작성 요청]\n'+fewshotRequest()+'\n\n[보고할 회의 메모]\n'+(state.fields.meetingNotes??defaultMeetingNotes());}
function trainingNav(label){return '<div class="row"><button class="secondary" id="trainBack">이전단계</button><button id="trainNext">다음단계</button></div><p class="small" id="notice" aria-live="polite"></p>';}
function trainingView(){const n=state.trainingPage||0;const f=state.fields;let body='';const note=t=>'<div class="bubble"><b>선임:</b> '+t+'</div>';if(n===0){body=note(esc(state.name)+' 님, 루키의 첫 결과가 도착했어요. 자료와 지시가 충분했는지 함께 확인해봅시다.')+'<section class="panel"><h3>오늘 맡긴 업무</h3><p><b>함께 수행할 업무</b><br>'+esc(f.selectedTask)+'</p><p><b>루키에게 맡길 일</b><br>'+esc(f.aiTask)+'</p><div class="dialog"><b>'+esc(state.name)+':</b> “루키, 오늘 너에게는 '+esc(f.aiTask)+'을 맡길 예정이야.”</div></section><section class="panel"><h3>루키의 첫 제출물</h3><p><b>루키:</b> “자료가 없어서 일반적인 상황으로 정리했고, 부족한 내용은 제가 채웠습니다!”</p><div class="error-sheet">고객 반응은 대체로 긍정적입니다. 만족도는 <b>95%</b>이며, 다음 달 성과는 <b>20% 향상</b>될 것으로 예상합니다. 현재 계획대로 진행하면 됩니다.</div><p class="small">실제 AI 답변이 아닌 수업용 오류 사례입니다. 수치의 근거가 없습니다.</p></section>'+choices('accident','이 결과를 어떻게 처리할까요?',['수치까지 있으니 그대로 사용한다.','근거를 확인하고, 자료와 조건을 넣어 다시 지시한다.'],1,'지시가 부족했다고 해서 근거 없는 수치가 사실이 되지는 않습니다. 자료와 기준을 보완하고 결과를 검토하세요.')+trainingNav('업무 지시 방법 배우기');}
else if(n===1){const qi=Math.min(state.quizIndex||0,4);const q=basicQuiz[qi];body=note('배운 내용을 적용해볼까요? 루키가 일을 제대로 할 수 있도록 더 구체적인 지시를 골라주세요.')+'<section class="panel instruction-test"><div class="row"><h3>업무 지시 테스트</h3><span class="small">'+(qi+1)+' / 5</span></div><div class="quiz-dots" aria-label="문제 진행 상황">'+basicQuiz.map((x,i)=>'<span class="'+(state.answers['basic'+i]===x[3]?'passed':'')+(i===qi?' current':'')+'">'+(i+1)+'</span>').join('')+'</div>'+choices('basic'+qi,q[1],q[2],q[3],'<b>'+esc(q[0])+'</b> · '+q[4])+'<div class="row quiz-navigation"><button class="secondary" id="quizPrev" '+(qi===0?'disabled':'')+'>이전 문제</button><button id="quizNext" '+(qi===4?'disabled':'')+'>다음 문제 →</button></div></section>'+trainingNav('내 업무 지시서 만들기');}
else if(n===2){body='<div class="bubble email-dialogue" role="note"><b>'+esc(state.name||'사수')+' → 루키</b><p>“이번 업무를 위해 회의를 개최하려고 해요. 루키, 먼저 팀 회의 소집 이메일을 작성해주세요.”</p><span class="small">회의에서 논의할 업무: '+esc(f.selectedTask||'앞에서 선택한 업무')+'</span></div>'+'<section class="panel"><h3>1. 바뀌는 정보만 채우기</h3><p class="small">실습에는 가상 정보를 사용하세요.</p>'+emailInput('meetingTo','[수신자]','예: 상품기획팀 팀원')+emailInput('meetingPurpose','[회의 목적]',f.selectedTask||'예: 고객 리뷰 분석 결과 논의')+emailInput('meetingTime','[일시]','예: 10월 15일 오후 2시')+emailInput('meetingPlace','[장소]','예: 2층 회의실')+emailInput('meetingPrepare','[준비 사항]','예: 검토할 리뷰 3개 준비')+emailInput('meetingTone','[말투]','예: 정중하고 간결하게')+'</section><section class="panel"><h3>2. 고정된 틀 + 바뀌는 [ ] 값</h3><p class="prompt-help">왼쪽에 입력하면 아래 지시서의 [ ] 값이 바로 바뀝니다. 작성 순서와 확인 규칙은 그대로 유지됩니다.</p><pre id="emailPreview" class="mission-prompt">'+emailPromptHtml()+'</pre><button id="emailCopy">이메일 작성 프롬프트 복사</button><p class="small">복사한 지시서를 생성형 AI에 전달해 루키에게 이메일 초안을 요청하세요.</p></section>'+trainingNav('이메일 제출 형식 정하기');}
else if(n===3){if(f.meetingNotes===undefined)f.meetingNotes=defaultMeetingNotes();body='<div class="bubble markdown-dialogue"><b>'+esc(state.name||'사수')+' → 루키</b><p>“회의가 끝났어요. 이 메모를 팀원들이 한눈에 읽을 수 있는 회의록으로 정리해주세요.”</p></div><section class="panel"><h3>루키에게 전달할 회의 메모 원본</h3><p class="small">앞에서 소집한 회의를 진행했다고 가정한 가상 메모입니다.</p><pre class="meeting-original">'+esc(f.meetingNotes)+'</pre></section><section class="panel"><h3>모범 지시문 · 마크다운으로 회의록 정리하기</h3><pre class="mission-prompt">'+esc(markdownModel())+'</pre><button id="minutesCopy">지시문 + 회의 메모 복사</button><p class="small">모범 지시문과 왼쪽 회의 메모를 함께 복사합니다. 생성형 AI에 붙여넣어 루키에게 회의록 작성을 요청하세요.</p></section>'+trainingNav('우리 팀의 작성 예시 알려주기');}
else{const tab=state.exampleTab===1?1:0;const e=teamExamples[tab];body='<div class="bubble fewshot-dialogue"><b>'+esc(state.name||'사수')+' → 루키</b><p>“회의록은 잘 정리했어요. 이제 팀장님께 보고해야 해요. 아래 우리 팀의 보고 예시처럼, 같은 문체와 양식으로 작성해주세요.”</p></div><section class="panel"><h3>우리 팀의 작성 예시</h3><p class="small">실습용 가상 사내 문서입니다. 두 문서의 공통된 문체와 항목 순서를 살펴보세요.</p><div class="example-tabs" role="tablist" aria-label="보고 예시"><button role="tab" id="exampleTab0" data-example-tab="0" aria-selected="'+(tab===0)+'" aria-controls="teamExample" class="'+(tab===0?'active':'')+'">예시 1 · 고객 문의 분석</button><button role="tab" id="exampleTab1" data-example-tab="1" aria-selected="'+(tab===1)+'" aria-controls="teamExample" class="'+(tab===1?'active':'')+'">예시 2 · 상품 비교</button></div><article id="teamExample" role="tabpanel" aria-labelledby="exampleTab'+tab+'" class="team-document"><h3>['+esc(e.title)+']</h3>'+e.rows.map((t,i)=>'<p><b>'+reportLabels[i]+'</b><span>'+esc(t)+'</span></p>').join('')+'</article></section><section class="panel"><h3>루키에게 보고서 작성 요청하기</h3><pre class="mission-prompt">'+esc(fewshotRequest())+'</pre><button id="workCopy">예시 2개 + 지시문 + 회의 메모 복사</button><p class="small">현재 선택한 탭과 관계없이 두 예시를 모두 복사합니다. 앞 단계의 회의 메모도 자동으로 포함됩니다. 생성형 AI에 붙여넣어 보고서를 요청하세요.</p></section>'+trainingNav('업무 보안 확인하기');}
return '<h1>'+['10:30 · 루키의 첫 결과물, 뭔가 이상하다','10:40 · 루키에게 제대로 지시할 수 있을까?','11:00 · [ ] 템플릿: 틀은 고정하고, 조건만 바꿔 재사용하기','11:15 · 마크다운: 긴 회의 메모를 한눈에 읽는 회의록으로','11:30 · 퓨샷: 예시로 우리 팀의 문체와 양식 알려주기'][n]+'</h1><div class="training-track">'+trainingTitles.map((t,i)=>'<span class="'+(i===n?'active':i<n?'complete':'')+'">'+(i+1)+'. '+t+'</span>').join('')+'</div>'+body;}
function trainingValid(){const n=state.trainingPage||0;const req={0:[],1:[],2:['meetingTo','meetingPurpose','meetingTime','meetingPlace','meetingPrepare','meetingTone'],3:[],4:[]}[n];const qs=n===0?[['accident',1]]:n===1?basicQuiz.map((q,i)=>['basic'+i,q[3]]):[];return req.every(k=>state.fields[k]?.trim())&&qs.every(([k,v])=>state.answers[k]===v);}
function bindTraining(){document.querySelectorAll('[data-example-tab]').forEach(e=>e.onclick=()=>{state.exampleTab=Number(e.dataset.exampleTab);save();render();document.getElementById('exampleTab'+state.exampleTab)?.focus()});const on=(id,fn)=>{const e=document.getElementById(id);if(e)e.onclick=fn};on('minutesCopy',()=>copy(minutesPrompt()));on('emailCopy',()=>copy(emailPrompt()));on('emailCopy2',()=>{if(!state.fields.meetingTime2?.trim()||state.fields.meetingTime2.trim()===state.fields.meetingTime?.trim()){document.getElementById('notice').textContent='다음 회의에는 다른 일시를 입력하세요.';return}copy(emailPrompt(true))});on('trainBack',()=>{if((state.trainingPage||0)>0)state.trainingPage--;else state.step=1;save();render()});on('trainNext',()=>{if(!trainingValid()){document.getElementById('notice').textContent='작성칸을 채우고 확인 문제를 모두 통과해주세요.';return}if((state.trainingPage||0)<4){if(state.trainingPage===2&&!state.fields.format)state.fields.format='draft';state.trainingPage=(state.trainingPage||0)+1;}else{state.fields.instruction=workPrompt();state.fields.method='[ ] 템플릿 · 마크다운 · 퓨샷 예시';state.step=3;}save();render()});on('quizPrev',()=>{state.quizIndex=Math.max(0,(state.quizIndex||0)-1);save();render()});on('quizNext',()=>{const i=state.quizIndex||0;if(state.answers['basic'+i]!==basicQuiz[i][3]){document.getElementById('notice').textContent='현재 문제를 통과한 뒤 다음 문제로 이동하세요.';return}state.quizIndex=Math.min(4,i+1);save();render()});document.querySelectorAll('[data-format]').forEach(e=>e.onclick=()=>{state.fields.format=e.dataset.format;save();render()});const data=document.getElementById('dataChoice');if(data)data.onchange=()=>{if(!data.value)return;if(state.fields.source&&!confirm('작성한 자료를 선택한 가상 자료로 교체할까요?'))return;state.fields.source=sampleData[data.value];save();render()};const setExample=text=>{if(state.fields.example&&!confirm('작성한 예시를 새 예시로 교체할까요?'))return;state.fields.example=text;save();render()};on('exampleAnalysis',()=>setExample('예시 1\n입력: 디자인은 예쁜데 뚜껑이 잘 열리지 않아요.\n출력: 장점: 디자인 / 불편: 뚜껑을 열기 어려움 / 확인할 일: 다른 리뷰에도 같은 불편이 있는지 확인\n\n예시 2\n입력: 가볍고 들고 다니기 편해요.\n출력: 장점: 가벼움과 휴대성 / 불편: 이 리뷰에서 확인되지 않음 / 확인할 일: 실제 제품 정보와 일치하는지 확인'));on('exampleWriting',()=>setExample('예시 1\n입력: 고객이 출고일을 문의함. 출고일은 아직 확인되지 않음.\n출력: 문의해 주셔서 감사합니다. 현재 출고 일정을 확인 중이며, 확인되는 대로 안내드리겠습니다.\n\n예시 2\n입력: 생활 방수 원단을 사용한 백팩. 완전 방수는 확인되지 않음.\n출력: 생활 방수 원단으로 가벼운 물 튀김에 대비한 데일리 백팩입니다. 완전 방수 여부는 별도 확인이 필요합니다.'));on('workCopy',()=>copy(workPrompt()));}

const securityCases=[
['개인정보','정확하게 분석하려고 고객 이름과 전화번호가 있는 명단을 일반 생성형 AI에 넣겠습니다.',1,'루키, 고객 명단은 입력하지 말고 실습용 가상 자료를 사용하세요.','개인정보 입력 금지 · 기업 기밀 보호'],
['학습 제외 설정','학습에 사용하지 않도록 설정했으니 회사 비밀번호도 입력해도 되겠죠?',1,'루키, 학습 제외 설정을 켜도 비밀번호를 입력하면 안 됩니다.','학습 데이터 제외 설정 · 보안정보 입력 금지'],
['사실 확인','회의 메모에 기한이 없어서 다음 주 금요일로 채웠습니다.',1,'루키, 없는 기한을 만들면 안 돼요. 확인 필요로 표시하고 담당자에게 확인합시다.','팩트체크 및 교차 검증 · 비판성'],
['투명성','AI로 초안을 작성했고, 아직 사실 검토 전이라고 표시하겠습니다.',0,'좋아요. AI 활용과 검토 상태를 정확히 밝히고, 검토가 끝난 뒤에만 검증 완료라고 표시하세요.','투명한 출처 표기 · 투명성'],
['저작권과 외부 공유','경쟁사 광고와 아주 비슷하지만 보기 좋으니 바로 게시하겠습니다.',1,'루키, 바로 게시하지 말고 유사성과 사용 가능 여부를 검토합시다. 외부 공개할 정보도 점검하세요.','결과물 검토 후 사용 · 저작권 확인 · 외부 공유 점검'],
['보안 사고 대응','회사 기밀을 잘못 입력했습니다. 작업을 중단하고 즉시 선임과 보안 담당자에게 알리겠습니다.',0,'좋아요. 숨기지 말고 즉시 보고한 뒤 담당자의 대응 지침을 따르세요.','보안 이상 즉시 신고 · 책임성']
];
function securityPassed(){return securityCases.every((q,i)=>state.answers['secure'+i]===q[2]);}
function securityView(){const i=Math.min(Math.max(state.securityIndex||0,0),5),q=securityCases[i],answer=state.answers['secure'+i],correct=answer===q[2],all=securityPassed();return '<h1>14:00 · 루키의 업무 보안 테스트</h1><div class="bubble security-dialogue"><b>'+esc(state.name||'사수')+' → 루키</b><p>“보고서를 보내기 전에 보안 점검부터 할게요. 루키, 자료를 어떻게 사용하고 결과를 어떻게 공유할지 말해보세요.”</p></div><section class="panel security-test"><div class="row"><span class="tag">상황 '+(i+1)+' / 6</span><b>'+q[0]+'</b></div><div class="security-tabs" aria-label="상황 선택">'+securityCases.map((x,j)=>'<button data-security-tab="'+j+'" aria-current="'+(i===j?'step':'false')+'" class="'+(i===j?'active':'')+' '+(state.answers['secure'+j]===x[2]?'passed':'')+'">'+(j+1)+'. '+x[0]+(state.answers['secure'+j]===x[2]?' ✓':'')+'</button>').join('')+'</div><div class="rookie-proposal"><b>루키의 제안</b><p>“'+q[1]+'”</p></div><h3>사수라면 어떻게 판단할까요?</h3><div class="security-actions">'+['승인하기','멈추고 수정하기'].map((t,j)=>'<button data-q="secure'+i+'" data-v="'+j+'" class="'+(answer===j?'chosen':'')+'">'+t+'</button>').join('')+'</div>'+(answer!==undefined?'<div class="feedback '+(!correct?'retry':'')+'" role="status"><b>'+(correct?'좋은 판단입니다.':'다시 판단해보세요.')+'</b><p><b>사수의 '+(q[2]===1?'수정 지시':'승인 지시')+':</b> '+q[3]+'</p></div>':'')+'<div class="security-controls"><button class="secondary" id="securityPrev" '+(i===0?'disabled':'')+'>이전 문제</button>'+'<button id="securityNext" '+(i===5||!correct?'disabled':'')+'>다음 문제</button>' +'</div>'+'</section><div class="row"><button class="secondary" id="back">이전단계</button><button id="securityFinish" '+(!all?'disabled':'')+'>다음단계</button></div><p class="small" id="notice" aria-live="polite"></p>';}
function bindSecurity(){const on=(id,fn)=>{const e=document.getElementById(id);if(e)e.onclick=fn};document.querySelectorAll('[data-security-tab]').forEach(e=>e.onclick=()=>{state.securityIndex=Number(e.dataset.securityTab);save();render()});on('securityPrev',()=>{state.securityIndex=Math.max(0,(state.securityIndex||0)-1);save();render()});on('securityNext',()=>{const i=state.securityIndex||0;if(state.answers['secure'+i]!==securityCases[i][2])return;state.securityIndex=Math.min(5,i+1);save();render()});on('securityFinish',()=>{if(!securityPassed())return;state.fields.security='PDF 기반 루키 보안 테스트 6개 상황 통과: 개인정보·학습 제외 설정·사실 확인·투명성·저작권과 외부 공유·보안 사고 대응';state.securityCompleted=true;state.step=4;save();render();scrollTo(0,0)});}

const launchProducts=[
{name:'포켓 오트 쿠키',data:'가격: 4개입 4,800원\n특징: 개별 포장, 귀리 사용, 쿠키 4개와 종이 상자\n주의: 밀·우유·달걀 함유. 직사광선을 피해 실온 보관\n확인되지 않은 정보: 열량·당 함량'},
{name:'데일리 미니 크로스백',data:'가격: 24,000원\n색상: 크림·블랙\n크기: 가로 20×세로 15×폭 6cm\n특징: 길이 조절 어깨끈, 내부 주머니 1개\n주의: 세탁기 사용 금지\n확인되지 않은 정보: 방수 여부·상품 무게·최대 수납 무게'},
{name:'모닝 텀블러',data:'가격: 18,000원\n색상: 라벤더·아이보리\n용량: 350mL\n특징: 스테인리스 본체, 분리 가능한 뚜껑\n주의: 전자레인지 사용 금지\n확인되지 않은 정보: 보온·보냉 지속 시간·완전 밀폐 여부'}];
function launchProduct(){return launchProducts[Number(state.fields.launchProduct)||0]}
function launchJob(){return state.fields.launchJob==='promo'?'SNS 홍보 문구':'온라인 스토어 상품 소개'}
function launchExamples(){return state.fields.launchJob==='promo'?'[예시 1 · 데스크 메모패드]\n문구: 오늘 할 일, 한 장으로 시작하세요.\n보조 설명: 체크박스가 있는 50매 메모패드로 하루의 계획을 정리해보세요.\n\n[예시 2 · 지퍼 펜 파우치]\n문구: 흩어진 필기구를 한곳에.\n보조 설명: 지퍼로 여닫는 한 칸 파우치에 자주 쓰는 필기구를 모아보세요.':'[예시 1 · 데스크 메모패드]\n한 줄 소개: 오늘 할 일을 한 장에 정리하세요.\n주요 특징: 체크박스가 인쇄된 메모패드로, 총 50매로 구성되어 있습니다.\n사용 장면: 책상에서 하루의 할 일을 기록할 때 사용할 수 있습니다.\n확인·주의: 종이 크기는 구매 전 상품 정보를 확인해주세요.\n\n[예시 2 · 지퍼 펜 파우치]\n한 줄 소개: 자주 쓰는 필기구를 한곳에 모아보세요.\n주요 특징: 지퍼로 여닫는 파우치이며, 내부 공간은 한 칸입니다.\n사용 장면: 학교나 사무실에서 필기구를 보관할 때 사용할 수 있습니다.\n확인·주의: 수납 가능한 필기구 수는 크기에 따라 달라집니다.'}
function launchMaterials(){return '# 상품 자료 · 수업용 가상 상품\n상품명: '+launchProduct().name+'\n'+launchProduct().data+'\n\n# 우리 팀의 작성 예시\n'+launchExamples()}
const launchInputKeys=['launchRole','launchPlace','launchAudience','launchFeature','launchLength','launchConstraint','launchUnknown'];
function launchDefaults(){const f=state.fields;if(f.launchRole===undefined)f.launchRole=f.launchJob==='promo'?'스마트스토어 SNS 홍보 담당자':'스마트스토어 상품 소개 담당자';if(f.launchPlace===undefined)f.launchPlace=f.launchJob==='promo'?'인스타그램 게시물':'온라인 스토어 상세페이지';if(f.launchConstraint===undefined)f.launchConstraint='제공한 상품 자료에 있는 사실만 사용하고, 없는 기능·수치·효과를 만들지 마.';if(f.launchUnknown===undefined)f.launchUnknown='확인되지 않은 정보는 추측하지 말고 확인 필요로 표시해 줘.'}
function launchScaffold(){const f=state.fields;const v=(k,label)=>f[k]?.trim()||label;return '# 역할\n너는 ['+v('launchRole','담당 역할')+']이야.\n\n# 목적\n['+launchProduct().name+']의 '+launchJob()+' 초안을 작성해 줘.\n\n# 맥락\n- 사용할 곳: ['+v('launchPlace','게시할 곳')+']\n- 대상 고객: ['+v('launchAudience','대상 고객 입력')+']\n- 강조할 특징: ['+v('launchFeature','강조할 특징 입력')+']\n\n'+launchMaterials()+'\n\n# 출력 형태\n- 두 예시와 같은 문체와 항목 구성으로 작성해 줘.\n- 결과의 개수 또는 분량: ['+v('launchLength','개수 또는 분량 입력')+']\n- 마지막에 사수가 확인해야 할 내용을 따로 정리해 줘.\n\n# 제약 조건\n- '+v('launchConstraint','사실에 근거하도록 지시')+'\n- '+v('launchUnknown','미확인 정보 처리 방법')+'\n- 예시는 문체와 양식만 참고하고, 상품 정보는 가져오지 마.'}
function launchInputsReady(){return launchInputKeys.every(k=>state.fields[k]?.trim())}
function launchInput(k,label,placeholder){return '<label for="'+k+'">'+label+'</label><input id="'+k+'" data-launch-input="'+k+'" value="'+esc(state.fields[k]||'')+'" placeholder="'+placeholder+'">'}
function careerReport(){const f=state.fields;return '[1차시] 희망 직업·직무에서 AI 활용 분석 / '+state.name+'\n\n희망 직업·직무: '+(f.interest||f.job||'상품기획 MD')+'\n1. 함께 수행할 업무: '+(f.selectedTask||'')+'\n2. AI에게 맡길 일: '+(f.aiTask||'')+'\n3. 내가 직접 확인·판단할 일: '+(f.humanTask||'')}
function launchReport(){const f=state.fields;return '[1차시] 나만의 업무 지시 / '+state.name+'\n상품: '+launchProduct().name+'\n업무: '+launchJob()+'\n\n[작성한 프롬프트]\n'+(f.finalPrompt||'')+'\n\n[AI 초안에서 선택·수정한 최종 결과물]\n'+(f.finalResult||'')+'\n\n[자료와 비교해서 확인한 내용]\n'+(f.finalCheck||'')+'\n\n[내가 선택·수정한 내용과 이유]\n'+(f.finalDecision||'')}
function launchView(){const n=Math.min(state.launchPage||0,3);const f=state.fields;let body='';const nav='<div class="row launch-nav"><button id="launchBack" class="secondary">이전단계</button>'+(n<3?'<button id="launchNext">다음단계</button>':'')+'</div><p id="notice" class="small" aria-live="polite"></p>';
if(n===0){body='<div class="bubble">선임: “'+esc(state.name)+' 님, 마지막 업무입니다. 상품 하나를 골라 루키에게 상품 소개나 홍보 문구를 맡겨보세요. 고객과 강조할 특징은 직접 정합니다.”</div><section class="panel"><h3>1. 상품과 업무 선택</h3><p class="small">모든 상품 정보와 작성 예시는 실습용 가상 자료입니다.</p><label for="launchProductSelect">상품</label><select id="launchProductSelect">'+launchProducts.map((p,i)=>'<option value="'+i+'" '+(Number(f.launchProduct||0)===i?'selected':'')+'>'+p.name+'</option>').join('')+'</select><label for="launchJobSelect">맡길 업무</label><select id="launchJobSelect"><option value="intro" '+(f.launchJob!=='promo'?'selected':'')+'>온라인 스토어 상품 소개</option><option value="promo" '+(f.launchJob==='promo'?'selected':'')+'>SNS 홍보 문구</option></select><h3>'+esc(launchProduct().name)+'</h3><pre>'+esc(launchProduct().data)+'</pre></section><section class="panel"><h3>우리 팀의 작성 예시 2개</h3><p class="small">아래 예시는 문체·양식 참고용 다른 상품입니다. 선택한 상품이 바뀌어도 예시는 같고, 맡길 업무에 따라 예시가 바뀝니다.</p><pre>'+esc(launchExamples())+'</pre><p class="small">따라 할 것은 문체와 양식입니다. 예시의 상품 특징은 가져오지 않습니다.</p></section>'}
else if(n===1){launchDefaults();f.finalPrompt=launchScaffold();body='<div class="bubble">선임: “왼쪽에서 업무 조건을 정해주세요. 입력한 내용은 오른쪽 [ ] 안에 바로 반영됩니다. 같은 상품도 누구에게, 무엇을 강조하느냐에 따라 다르게 소개할 수 있습니다.”</div><section class="panel launch-controls"><h3>2. 내 업무 조건 정하기</h3><b>'+esc(launchProduct().name)+' · '+launchJob()+'</b><details><summary>선택한 상품 자료와 예시 보기</summary><pre>'+esc(launchMaterials())+'</pre></details>'+launchInput('launchRole','역할','예: 상품 소개 담당자')+launchInput('launchPlace','사용할 곳','예: 온라인 스토어 상세페이지')+launchInput('launchAudience','대상 고객','예: 등교할 때 소지품을 간편하게 챙기는 학생')+launchInput('launchFeature','강조할 특징 · 상품 자료에서 선택','예: 내부 주머니 1개, 길이 조절 어깨끈')+launchInput('launchLength','결과의 개수 또는 분량','예: 200자 이내 소개 1개 / 홍보 문구 3개')+launchInput('launchConstraint','자료에 없는 내용을 만들지 않도록 지시','상품 자료에 있는 사실만 사용')+launchInput('launchUnknown','확인되지 않은 정보 처리 방법','추측하지 말고 확인 필요로 표시')+'</section><section class="panel launch-editor"><h3>완성되는 내 프롬프트</h3><p class="small">작성 틀이 미리 준비되어 있습니다. 왼쪽 입력값이 자동으로 반영됩니다.</p><pre id="launchPromptPreview" class="mission-prompt">'+esc(f.finalPrompt)+'</pre><button id="launchPromptCopy">내 프롬프트 복사</button><p class="small">복사한 내용을 평소 사용하는 생성형 AI에 붙여넣어 초안을 받으세요.</p></section>'}

else if(n===2){body='<div class="bubble">선임: “자료에 없는 내용을 루키가 만들지는 않았나요? 지시한 고객·형식에 맞는지도 확인한 뒤, 사용할 내용을 직접 선택해주세요.”</div><section class="panel"><h3>선택한 상품 자료</h3><b>'+esc(launchProduct().name)+'</b><p class="small">수업용 가상 상품 · 아래 자료를 근거로 확인하세요.</p><pre>'+esc(launchProduct().data)+'</pre><div class="feedback"><b>내가 요청한 조건</b><p>대상 고객: '+esc(f.launchAudience)+'<br>강조할 특징: '+esc(f.launchFeature)+'<br>개수·분량: '+esc(f.launchLength)+'</p></div></section><section class="panel launch-review"><h3>3. 검토</h3>'+field('finalResult','사용할 결과물','AI 초안에서 선택하거나 수정한 상품 소개·홍보 문구를 붙여넣으세요.')+field('finalCheck','1) 상품 자료와 다른 내용이 있나요?','예: 저칼로리는 자료에 없는 정보라 삭제했습니다. / 개별 포장은 상품 자료와 일치합니다.')+'<p class="small">가격·구성·특징을 비교하고, 자료에 없는 효능이나 성능을 추가하지 않았는지 확인하세요.</p>'+field('finalDecision','2) 내가 정한 고객에게 이 문구를 사용해도 될까요?','예: 학생에게 개별 포장의 장점을 전달하려고 가방에 하나씩 챙기기 좋은 간식으로 바꿨습니다.')+'<p class="small">대상 고객에게 어울리고, 강조하려던 특징이 잘 드러나는지 판단하세요. 수정이 필요 없다면 그대로 사용할 이유를 적으세요.</p></section>'}
else{body='<div class="bubble">선임: “초안을 확인하고 사용할 내용을 직접 판단했군요. 이제 팀장에게 보고하고 패들렛에 제출해주세요.”</div><section class="panel"><h3>팀장 보고 · 패들렛 제출</h3><details><summary>희망 직업·직무 분석 미리보기</summary><pre>'+esc(careerReport())+'</pre></details><button id="careerReportCopy">직무 분석 복사</button><p class="small">앞에서 작성한 학생 미션 3개와 희망 직무를 복사합니다.</p><button id="launchReportCopy">마지막 미션 복사</button><p class="small">내 프롬프트·최종 결과물·검토 내용을 복사합니다.</p><label for="padurl">패들렛 주소</label><input id="padurl" value="'+esc(f.padurl||'')+'" placeholder="https://padlet.com/…"><button id="padlet" class="secondary">패들렛 열기</button><p class="small">두 내용을 게시한 뒤 제출 완료를 누르세요.</p><button id="finish">'+(state.done?'1차시 제출 완료':'패들렛 제출 완료 · 승진하기')+'</button><div id="promotionConfirm" hidden class="feedback"><p>패들렛에 직무 분석과 마지막 미션을 게시했나요?</p><p class="small">게시 여부는 자동 확인하지 않습니다.</p><button id="confirmPromotion" type="button">게시 완료했습니다 · 승진하기</button><button id="cancelPromotion" type="button" class="secondary">아직 제출 전입니다</button></div>'+(state.done?'<div class="feedback"><b>선임: “자네, 대리로 승진일세!”</b><p>루키에게 구체적으로 지시하고, 초안을 확인한 뒤 사용할 내용을 직접 판단했군요.</p></div>':'')+'</section><section class="panel report-card"><h3>사원증</h3>'+card()+'<p class="small">'+(state.done?'1차시 미션을 완료했습니다.':'패들렛에 두 결과물을 게시하고 제출 완료 버튼을 누르세요.')+'</p>'+(state.done?'<button id="replay" class="secondary">승진 효과 다시 보기</button>':'')+'</section>'}
return '<h1>'+['15:00 · 루키에게 신상품 출시 업무 맡기기','15:00 · 루키에게 신상품 출시 업무 맡기기','15:00 · 루키에게 신상품 출시 업무 맡기기','16:30 · 팀장에게 보고하기'][n]+'</h1><div class="launch-track">'+(n===3?[]:['상품·업무 선택','프롬프트 작성','검토']).map((t,i)=>'<span class="'+(i===n?'active':'')+'">'+(i+1)+'. '+t+'</span>').join('')+'</div>'+body+nav}
function launchReady(){return ['finalPrompt','finalResult','finalCheck','finalDecision'].every(k=>state.fields[k]?.trim())}
function bindLaunch(){document.querySelectorAll('[data-launch-input]').forEach(e=>e.oninput=()=>{state.fields[e.dataset.launchInput]=e.value;state.fields.finalPrompt=launchScaffold();document.getElementById('launchPromptPreview').textContent=state.fields.finalPrompt;save()});const on=(id,fn)=>{const e=document.getElementById(id);if(e)e.onclick=fn};for(const k of ['launchProduct','launchJob']){const e=document.getElementById(k==='launchProduct'?'launchProductSelect':'launchJobSelect');if(e){const change=()=>{const value=e.value;if(String(state.fields[k]??(k==='launchProduct'?'0':'intro'))===value)return;if(state.fields.finalResult&&!confirm('상품 또는 업무를 바꾸면 결과물과 검토 내용이 초기화됩니다. 변경할까요?')){e.value=String(state.fields[k]??(k==='launchProduct'?'0':'intro'));return}state.fields[k]=value;if(k==='launchJob'){delete state.fields.launchRole;delete state.fields.launchPlace}delete state.fields.launchFeature;for(const f of ['finalResult','finalCheck','finalDecision'])delete state.fields[f];state.done=false;launchDefaults();state.fields.finalPrompt=launchScaffold();save();render()};e.onchange=change;e.oninput=change}}on('launchBack',()=>{if((state.launchPage||0)>0)state.launchPage--;else state.step=3;save();render()});on('launchNext',()=>{if(state.launchPage===1&&!launchInputsReady()){const e=document.querySelector('[data-launch-input="'+launchInputKeys.find(k=>!state.fields[k]?.trim())+'"]');e?.focus();document.getElementById('notice').textContent='대상 고객·강조할 특징·분량을 포함한 왼쪽 입력칸을 완성해주세요.';return}if(state.launchPage===1)state.fields.finalPrompt=launchScaffold();if(state.launchPage===2&&!launchReady()){document.getElementById('notice').textContent='사용할 결과물과 검토 1), 2)를 작성해주세요.';return}state.launchPage=Math.min(3,(state.launchPage||0)+1);save();render()});on('launchScaffold',()=>{if(state.fields.finalPrompt&&!confirm('작성한 프롬프트를 작성 틀로 교체할까요?'))return;state.fields.finalPrompt=launchScaffold();save();render()});on('launchMaterialCopy',()=>copy(launchMaterials()));on('launchPromptCopy',()=>{if(!launchInputsReady())return alert('왼쪽의 업무 조건을 모두 입력하세요.');state.fields.finalPrompt=launchScaffold();save();copy(state.fields.finalPrompt)});on('careerReportCopy',()=>copy(careerReport()));on('launchReportCopy',()=>{if(!launchReady())return alert('프롬프트와 결과물, 검토 두 항목을 작성해주세요.');copy(launchReport())})}

function render(){if(state.lesson===2||state.lesson===3){renderProject();return}let b='';if(state.step===0){b='<div class="arrival-heading"><div class="tag">YOUR FIRST DAY AT WORK</div><h1>스마트스토어 AI 운영팀의 하루</h1><p class="arrival-lead">오늘 배정된 AI 후임과 첫 업무를 완수하고,<br><strong>대리로 승진해 보세요.</strong></p></div><div class="panel orange arrival-intro"><h2>AI 후임 루키</h2><p>오늘 여러분에게 AI 후임 <strong>루키</strong>가 배정됐습니다. 초안 작성과 정리는 빠르지만, 회사 상황을 저절로 알지는 못합니다.</p><p>지시가 부족하면 되묻거나 추측하고, 빈칸을 마음대로 채워 그럴듯하게 틀린 내용을 만들기도 합니다.</p><p><strong>사수인 여러분이 업무를 나누고, 지시하고, 확인해야 합니다.</strong></p></div><div class="panel arrival-mission"><h2>오늘의 미션</h2><ol class="arrival-missions"><li>관심 직무에서 AI와 업무 나누기</li><li>루키에게 정확하게 업무 지시하기</li><li>세 가지 프롬프트 기법 익히기</li><li>루키의 보안 판단 점검하기</li><li>팀장 보고와 패들렛 제출하기</li></ol><div class="arrival-goal"><b>오늘의 목표</b><p>AI가 어떤 업무를 도울 수 있는지 알아보고, 그 과정에서 사람이 맡아야 할 검토와 판단을 설명할 수 있습니다.</p></div></div><aside class="arrival-card"><div id="liveCard">'+card()+'</div><div class="badge-name"><input aria-label="사원증 이름 또는 별명" id="name" value="'+esc(state.name)+'" placeholder="사원증에 표시할 이름 또는 별명" maxlength="30"></div><div class="portrait-picker"><label class="photo-file-button" for="portrait"><span>파일 선택</span><span id="portraitHint">사원증 사진 선택</span><input id="portrait" type="file" accept="image/*" aria-label="사원증 사진 선택"></label></div></aside><div class="arrival-actions"><button id="start">09:00 출근하기</button><button id="newStudent" class="secondary">처음부터 다시하기</button></div>';}else if(state.step===1){b='<h1>09:10 · 오늘 무슨 일을 맡길까요?</h1><div class="bubble">선임: “'+esc(state.name)+' 님, 오늘 새로 온 루키에게 업무를 배정해주세요. 먼저 관심 있는 직무에서 어떤 일을 하는지 AI 직무 코치에게 물어보고, 오늘 루키에게 맡길 일과 직접 확인할 일을 정해봅시다.”</div><div class="panel"><h3>학교에서 소개하는 진로</h3><p>온·오프라인 판매와 유통, 상품기획, 브랜드·마케팅·홍보</p><div class="grid"><div><b>푸드아트 코스</b><p>식품 온라인 창업, 식품 상품기획 MD/AMD, 온라인 스토어 운영</p></div><div><b>패션아트 코스</b><p>패션 상품 유통, 패션 상품기획 MD/AMD, 브랜드·마케팅 업무</p></div></div><p class="small">학교 안내의 진로를 참고하되, 본인이 관심 있는 다른 직무를 적어도 됩니다.</p><p class="prompt-help"><b>선임:</b> 오늘의 업무를 제안하는 사람<br><b>루키:</b> 여러분이 일을 맡길 AI 신입사원<br><b>AI 직무 코치:</b> 직무 탐색을 도와주는 평소 사용하는 생성형 AI</p></div><div class="panel"><h3>Copyable Prompt</h3><p class="prompt-help">AI 직무 코치는 평소 사용하는 생성형 AI(ChatGPT, Gemini 등)입니다. 직업·직무의 업무를 알아보는 데 도움을 줍니다.</p><div class="prompt-setup"><div><label>학년</label><input id="grade" value="'+esc(state.fields.grade||'2')+'" placeholder="2"></div><div><label>관심 직업·직무</label><input id="interest" value="'+esc(state.fields.interest||'상품기획 MD')+'" placeholder="예: 상품기획 MD"></div></div><pre class="mission-prompt" id="careerPrompt">'+esc(careerPrompt())+'</pre><button id="careerCopy">프롬프트 복사</button><p class="prompt-help">복사한 프롬프트를 붙여넣어 AI 직무 코치에게 질문하세요.</p></div><div class="panel"><h3>학생 미션</h3><p class="prompt-help">AI 직무 코치의 답변을 나의 언어로 정리해서 작성합니다.</p>'+field('selectedTask','1. AI의 답변을 읽고, 함께 수행할 업무 1개를 고르세요.','예: 고객 리뷰 분석')+field('aiTask','2. 그 업무에서 AI에게 맡길 일을 구체적으로 적으세요.','예: 리뷰에서 자주 나오는 장점과 불만 정리')+field('humanTask','3. AI가 만든 결과에서 내가 직접 확인·판단할 일을 적으세요.','예: 요약이 실제 리뷰와 맞는지 확인하고 개선할 불만 판단')+'</div>'+navigation();}else if(state.step===2){b=trainingView();}else if(state.step===3){b=securityView();}else{b=launchView();}

app.innerHTML=state.step===0?b:shell(b);bind();addLessonMenu();document.querySelectorAll('textarea').forEach(e=>{growInput(e);e.addEventListener('input',()=>growInput(e))});}
function growInput(e){e.style.setProperty('height','auto','important');e.style.setProperty('height',Math.max(100,e.scrollHeight+2)+'px','important');e.style.overflowY='hidden'}
function careerPrompt(){return '너는 특성화고 학생의 진로와 취업을 돕는 AI 직무 코치야.\n나는 제일여상 '+(state.fields.grade||'2')+'학년 학생이고,\n['+(state.fields.interest||'상품기획 MD')+']에 관심이 있어.\n\n내가 선택한 직업·직무에서 실제로 수행하는\n주요 업무 5개를 골라 표로 정리해 줘.\n\n선택한 직업·직무의 범위를 유지하고,\n관련된 다른 직업·직무를 5개 나열하지 마.\n예를 들어 상품기획 MD를 선택했다면,\n바잉 MD나 온라인 MD를 나열하는 대신\n고객 요구 조사, 경쟁 상품 분석, 신상품 콘셉트 기획처럼\n상품기획 MD가 수행하는 업무를 정리해 줘.\n\n표는 다음 5개 열로 구성해 줘.\n① 주요 업무명\n② 사람이 수행하는 구체적인 일\n③ AI가 도와줄 수 있는 구체적인 일\n④ 사람이 반드시 확인·판단해야 할 일\n⑤ 해당 업무에 필요한 AI 활용 역량\n\n고등학교 2학년 학생이 이해할 수 있는 쉬운 표현으로 작성하고,\nAI에게 맡길 일과 사람이 확인·판단할 일이\n서로 연결되도록 설명해 줘.';}function report(){return '[1차시] AI 직원 업무 분담 보고 / '+state.name+'\n\n관심 직무: '+(state.fields.interest||state.fields.job||'')+'\n오늘 함께 수행할 업무: '+(state.fields.selectedTask||'')+'\nAI에게 맡길 업무: '+(state.fields.aiTask||'')+'\n내가 판단·확인할 일: '+(state.fields.humanTask||'')+'\n\n업무 지시 예시: '+(state.fields.instruction||'')+'\n적용할 지시 방법: '+(state.fields.method||'')+'\n회의록 정리 지시: '+markdownModel()+'\n보안 규칙과 행동: '+(state.fields.security||'');}
function bind(){const photo=document.getElementById('portrait');if(photo)photo.onchange=async()=>{const file=photo.files?.[0];if(!file)return;const hint=document.getElementById('portraitHint');hint.textContent='사진 불러오는 중';let url;try{url=URL.createObjectURL(file);const img=new Image();await new Promise((resolve,reject)=>{img.onload=resolve;img.onerror=reject;img.src=url});const canvas=document.createElement('canvas');canvas.width=canvas.height=320;const ctx=canvas.getContext('2d');const side=Math.min(img.naturalWidth,img.naturalHeight);ctx.drawImage(img,(img.naturalWidth-side)/2,(img.naturalHeight-side)/2,side,side,0,0,320,320);const data=canvas.toDataURL('image/jpeg',.85);localStorage.setItem('store-ai-portrait-v1',data);portrait=data;hint.textContent=file.name;document.getElementById('liveCard').innerHTML=card()}catch{hint.textContent='사진을 불러오지 못했습니다. JPG 또는 PNG를 선택하세요.'}finally{if(url)URL.revokeObjectURL(url);photo.value=''}};const remove=document.getElementById('removePhoto');if(remove)remove.onclick=()=>{portrait='';try{localStorage.removeItem('store-ai-portrait-v1')}catch{}document.getElementById('liveCard').innerHTML=card();photo.value='';document.getElementById('portraitHint').textContent='사원증 사진 선택'};bindTraining();bindSecurity();bindLaunch();document.querySelectorAll('[data-k]').forEach(e=>e.oninput=()=>{state.fields[e.dataset.k]=e.value;const minutesPreview=document.getElementById('minutesPreview');if(minutesPreview)minutesPreview.textContent=minutesPrompt();const emailPreview=document.getElementById('emailPreview');if(emailPreview)emailPreview.innerHTML=emailPromptHtml();const preview=document.getElementById('workPreview');if(preview)preview.textContent=workPrompt();save()});document.querySelectorAll('[data-q]').forEach(e=>e.onclick=()=>{state.answers[e.dataset.q]=Number(e.dataset.v);save();render()});for(const k of ['grade','interest']){const e=document.getElementById(k);if(e)e.oninput=()=>{state.fields[k]=e.value;document.getElementById('careerPrompt').textContent=careerPrompt();save()}}const on=(id,f)=>{const e=document.getElementById(id);if(e)e.onclick=f};const name=document.getElementById('name');if(name)name.oninput=()=>{state.name=name.value;const c=document.getElementById('liveCard');if(c)c.innerHTML=card();save()};on('newStudent',()=>{if(!document.getElementById('restartDialog')){const d=document.createElement('dialog');d.id='restartDialog';d.innerHTML='<p>작성한 이름·사진·진행 내용을 지우고 처음부터 시작할까요?</p><div class="row"><button id="restartYes" type="button">처음부터 다시하기</button><button id="restartNo" class="secondary" type="button">취소</button></div>';document.body.append(d);d.querySelector('#restartNo').onclick=()=>d.close();d.querySelector('#restartYes').onclick=()=>{clearTimeout(timer);try{localStorage.removeItem('store-ai-day-v1');localStorage.removeItem('store-ai-portrait-v1')}catch{}portrait='';state={name:'',step:0,fields:{},answers:{},done:false,token:crypto.randomUUID()};d.close();render();save();document.getElementById('name').focus()}}document.getElementById('restartDialog').showModal()});on('start',()=>{if(!state.name.trim())return alert('이름 또는 별명을 입력하세요.');state.step=1;save();render();scrollTo(0,0)});on('back',()=>{if(state.step===3)state.trainingPage=4;state.step=Math.max(0,state.step-1);save();render();scrollTo(0,0)});on('next',()=>{const required={1:['selectedTask','aiTask','humanTask'],2:['instruction','method'],3:['security']}[state.step];const q={1:{},2:{email:1,report:1,insight:1},3:{privacy:1,training:1,ad:1}}[state.step];if(required.some(k=>!state.fields[k]?.trim())||Object.entries(q).some(([k,v])=>state.answers[k]!==v)){document.getElementById('notice').textContent='작성칸과 상황 판단을 확인하고 다시 진행하세요.';return}state.step++;if(state.step===2)state.trainingPage=0;save();render();scrollTo(0,0)});on('careerCopy',()=>copy(careerPrompt()));on('copy',()=>copy(report()));on('tokenCopy',()=>copy(state.token));const u=document.getElementById('padurl');if(u)u.oninput=()=>{state.fields.padurl=u.value;save()};on('padlet',()=>{try{const u=new URL(state.fields.padurl);if(u.protocol!=='https:'||!(u.hostname==='padlet.com'||u.hostname.endsWith('.padlet.com')))throw Error();window.open(u.href,'_blank','noopener')}catch{alert('https://padlet.com/으로 시작하는 패들렛 주소를 입력하세요.')}});on('finish',()=>{if(state.done){celebrate();return}const box=document.getElementById('promotionConfirm');if(!launchReady()){document.getElementById('notice').textContent='이전 검토 화면에서 사용할 결과물과 검토 두 항목을 작성해주세요.';document.getElementById('notice').scrollIntoView({block:'nearest'});return}box.hidden=false;document.getElementById('confirmPromotion').focus()});on('cancelPromotion',()=>{document.getElementById('promotionConfirm').hidden=true});on('confirmPromotion',()=>{state.done=true;state.completedAt=new Date().toLocaleString('ko-KR',{timeZone:'Asia/Seoul'});render();celebrate();save();void sync()});on('replay',celebrate);}
async function copy(t){try{await navigator.clipboard.writeText(t);alert('복사했습니다.')}catch{const e=document.createElement('textarea');e.value=t;document.body.append(e);e.select();document.execCommand('copy');e.remove();alert('복사했습니다.')}}function save(){try{localStorage.setItem('store-ai-day-v1',JSON.stringify(state));document.getElementById('status').textContent='이 기기에 저장됨';}catch{document.getElementById('status').textContent='저장 공간을 확인해주세요'}clearTimeout(timer);timer=setTimeout(sync,650)}async function sync(){return true}function celebrate(){const d=document.createElement('div');d.className='celebrate';for(let i=0;i<75;i++){const c=document.createElement('i');c.className='confetti';c.style.left=Math.random()*100+'%';c.style.background=['#ffa800','#00a6d4','#e95d70','#8b6fea'][i%4];c.style.animationDelay=Math.random()*.8+'s';d.append(c)}document.body.append(d);setTimeout(()=>d.remove(),4000)}

